quests[98901] = { id = 98901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkspear Islands Clash", description = "The battle against the Darkspear Raiders is heating up. Without urgent aid, the Darkspear Islands will be lost to us. \n\nIt is your duty as a proud member of the Alliance to ensure this does not happen. Bring me proof of your contributions on the front lines and you will be revered as a hero of the Alliance!", sourceObjective = "Bring 3 Darkspear Islands Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", sourceObjectiveStatus = "unverified-source-field" }
quests[98903] = { id = 98903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Darkspear Islands!", description = "Go forth and represent the Theramore Expeditionary Force in battle at Darkspear Islands, {name}! Achieve victory and show these Horde dogs the might of the Alliance!", sourceObjective = "Win a Darkspear Islands battleground and return back to Brelinda McFarry at Northwatch Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[98906] = { id = 98906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Darkspear Islands!", description = "The battle at the Darkspear Islands be locked in a stalemate, {class}. Show those Alliance fools who the superior force is. \n\nCarry your head high in service of the Darkspear and claim victory in battle. The Loa will surely be givin' you their blessing, {class}!", sourceObjective = "Win a Darkspear Islands battleground and return back to Nizook Boof at The Merchant Coast.", sourceObjectiveStatus = "unverified-source-field" }
quests[98977] = { id = 98977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mossheart the Elder" }
quests[98983] = { id = 98983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostleaf the Elder" }
quests[99046] = { id = 99046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Runner", description = "The Council of the Forest sent a small group of sentinels to the Oracle Tree some time ago. The tree sends messages to our elders, and it falls to us to deliver them to Darnassus safely.\n\nI received word that our most recent runner has not yet arrived. The Oracle's messages vary in frequency, but it has been abnormally long.\n\nPlease head towards the Oracle Glade along the road to the west and check on her. It would have been Eralya Leafshadow's turn, and she is still in training. Elune guide you.", sourceObjective = "Search for Sentinel Eralya Leafshadow on the road leading to the Oracle Glade.", completion = "Elune's grace... I shall not die... alone...", sourceObjectiveStatus = "unverified-source-field" }
quests[99047] = { id = 99047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Dead Yet", description = "My sisters and I... were dispatched... Oracle Tree...\n\nTree... message. I... harpies... everywhere...\n\n<Eralya coughs up blood, grimacing through the pain.>\n\nI may not have long... no one coming. Please... Byancie... in Dolanaar...", sourceObjective = "Seek aid from Byancie in Dolaanar for Sentinel Eralya Leafshadow.", completion = "The harpies have become afflicted by the same foulness showing up throughout the forest. I'm sure that is what ails Sentinel Eralya as well.\n\nWe must hurry. It won't be long before she succumbs to her injuries.", sourceObjectiveStatus = "unverified-source-field" }
quests[99048] = { id = 99048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Missing Hand", description = "A member of the Shattered Hand, a group of more... subtle fighters, was watching Tiragarde Keep from a distance. Her reports suddenly stopped coming in.\n\nI doubt the humans would have caught her, so I'm concerned something more dangerous is at play. See if you can find her. Hopefully the messages are just delayed.", sourceObjective = "Find Heglan Shadeeye north of Tiragarde Keep.", completion = "Heglan's body lies cold within the wreckage of the hut.\n\nWhatever killed her doesn't seem to be human. There may be signs of what happened nearby.", sourceObjectiveStatus = "unverified-source-field" }
